-- Formats de chaque parfum, comme chez Chogan : 70 ml / 30 ml / 15 ml (recharge),
-- 50 ml / 15 ml pour la gamme Luxury et les Signatures. Prix = prix public Chogan converti en FCFA + 25 %.
-- Chaque format a son propre stock (ProductVariant) ; le stock actuel du produit passe sur le format principal.
ALTER TABLE "ProductVariant" ADD COLUMN IF NOT EXISTS "code" TEXT;

CREATE TEMP TABLE _formats (code TEXT PRIMARY KEY, volumes JSONB) ON COMMIT DROP;

-- Formats posés une seule fois (un format déjà défini à la main n'est pas écrasé).
UPDATE "Product" AS p
SET "volumes" = f.volumes, "updatedAt" = now()
FROM _formats f
WHERE p."choganCode" = f.code
  AND (p."volumes" IS NULL OR jsonb_typeof(p."volumes"::jsonb) <> 'array' OR jsonb_array_length(p."volumes"::jsonb) = 0);

SELECT 'var-' || p."id" || '-' || (v.ord - 1), p."id", v.item->>'label', v.item->>'code',
       CASE WHEN v.ord = 1 THEN p."stock" ELSE 0 END, CASE WHEN v.ord = 1 THEN p."lowStockThreshold" ELSE 3 END
FROM "Product" p
JOIN _formats f ON f.code = p."choganCode"
CROSS JOIN LATERAL jsonb_array_elements(f.volumes) WITH ORDINALITY AS v(item, ord)
ON CONFLICT ("productId", "volumeLabel") DO NOTHING;
